(function () {
  'use strict';
  const chunkSet = {"title":"Text Evidence","topic":"Reading Comprehension","questions":[{"id":"reading-comprehension-text-evidence-q0101","version":3,"contentHash":"sha256:9be7ccda817b111f6d382989d5adb2bcbb32345437d08c0cdc17b7da9bf8e151","question":"Read the passage. Grade 4 foundation passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["The nurse checked the first-aid supplies after lunch.","By winter break, the school ordered fewer boxes of printer paper.","The passage says every reader already knew about recycling team.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting details are the sentences in a text that provide evidence, facts, or examples to prove a main idea is true.","example":"Main idea: The park is popular. Detail: Hundreds of people visit the park every Saturday.","strategyClue":"Look for the sentence that shows a result or an effect of the recycling plan. Ask yourself, 'Which sentence proves that the school's behavior had a measurable impact?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence provides evidence that the school's paper consumption decreased, which directly supports the claim that the plan changed the amount of paper used.","incorrect":[{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence mentions items unrelated to paper recycling and does not provide any evidence about how much paper the school used."},"",{"choice":"The passage says every reader already knew about recycling team.","category":"not in text","reason":"This claim is not supported by the passage and fails to describe the impact of the recycling bins on paper usage."},{"choice":"The title names the topic but gives no proof.","category":"unsupported reasoning","reason":"While titles describe topics, they do not provide the concrete evidence needed to prove that the school's paper usage habits changed."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":101,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0102","version":3,"contentHash":"sha256:696505e1829646a346e0abc3f24d7012e7dd514d5b88a598e62ffccfa221e336","question":"Read the passage. Grade 4 foundation passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["The passage says every reader already knew about museum exhibit.","A rainstorm delayed the baseball game.","Visitors could press buttons to hear recordings of elders telling memories.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Evidence refers to specific facts, details, or quotes from a text that directly support a claim or answer a question.","example":"Claim: The garden is growing well. Evidence: 'The tomatoes turned red and the sunflowers grew taller than the fence.'","strategyClue":"Look for the specific words in the answer choices that describe physical items and spoken accounts; then, verify if the passage actually mentions both of those elements.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This sentence provides direct evidence of personal stories, which combined with the listed objects like tools and photographs, confirms the exhibit featured both.","incorrect":[{"choice":"The passage says every reader already knew about museum exhibit.","category":"unsupported information","reason":"The text never states that readers already knew about the exhibit; this is not evidence found within the passage."},{"choice":"A rainstorm delayed the baseball game.","category":"irrelevant information","reason":"This detail is not in the passage and has no connection to the museum exhibit or the museum workers."},"",{"choice":"The title names the topic but gives no proof.","category":"lack of evidence","reason":"A title is just a label, not an example of the contents inside the exhibit; we need specific details to prove what was included."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":102,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0103","version":3,"contentHash":"sha256:e027a76fe60c09bff9196d780256f38b3a125f8aeb52107427c4a1f10ee1a056","question":"Read the passage. Grade 4 foundation passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["The title names the topic but gives no proof.","The principal announced picture day over the speaker.","The passage says every reader already knew about robotics club.","Each time the robot missed a turn, members adjusted the code and tested again."],"correct":3,"studyAid":{"definition":"Supporting evidence consists of specific details or actions from a text that prove a claim or main idea is true.","example":"Claim: The cat was hungry. Evidence: The cat stood by his empty bowl and meowed loudly.","strategyClue":"Look for a sentence that describes an action taken by the subjects in response to a problem. If the sentence shows them fixing something that went wrong, it is likely the evidence you need.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence shows the students treating a 'missed turn' (a mistake) as a reason to adjust their work, which demonstrates that they are using the error as information to improve.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not in text","reason":"This sentence is not present in the passage and does not provide any evidence for how the students handled their mistakes."},{"choice":"The principal announced picture day over the speaker.","category":"irrelevant information","reason":"This information is not related to the robotics club or how they used mistakes to improve their project."},{"choice":"The passage says every reader already knew about robotics club.","category":"unsupported claim","reason":"The passage does not state that readers were already informed about the club, nor does this sentence show how the students reacted to their robot's errors."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":103,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0104","version":3,"contentHash":"sha256:3ec39ee32a1a6b69458e5f401a20aa9371a426ffb6ee89df039a507eae00a233","question":"Read the passage. Grade 4 foundation passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["Students who arrived close to the bell could still choose a quick meal.","The science lab received new magnifying glasses.","The passage says every reader already knew about school breakfast.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Strong evidence is a specific fact or sentence from the text that directly supports your claim or answers the question being asked.","example":"Claim: The park is popular. Evidence: Every bench was taken and children were waiting for the swings.","strategyClue":"Highlight the key words in the question, then scan each option to see which one explicitly describes the concept of time management or student schedules.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This sentence explicitly links the timing of student arrival (arriving just before class) to the availability of the food, providing direct evidence that the cart serves those with limited time.","incorrect":["",{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information provided","reason":"This detail discusses science lab equipment, which has no connection to the school breakfast cart or the time students have before class."},{"choice":"The passage says every reader already knew about school breakfast.","category":"not supported by text","reason":"This statement is not present in the passage and does not help prove anything about the cart's design or student arrival times."},{"choice":"The title names the topic but gives no proof.","category":"missing evidentiary support","reason":"A title might introduce a subject, but it cannot serve as evidence to prove a specific point about the efficiency of the breakfast program."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":104,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0105","version":3,"contentHash":"sha256:84bb4b82e6f2524576ac27b645272db4f1cf76ee554d2f1ad3116b91913ce950","question":"Read the passage. Grade 4 foundation passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["The post office closed early on Saturday.","They added arrows, distance signs, and small plaques naming common trees.","The passage says every reader already knew about nature trail.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To support an idea using a text, find specific sentences that provide evidence or examples for that claim.","example":"Claim: The park had many amenities. Evidence: 'A new bench gave hikers a place to rest near the creek.'","strategyClue":"Break the main idea into two parts: 'directions' and 'information.' Scan the sentences to find words that match each part, then see which sentence contains examples for both.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. The word 'arrows' supports the idea of giving directions, and 'plaques naming common trees' supports the idea of giving information.","incorrect":[{"choice":"The post office closed early on Saturday.","category":"irrelevant information","reason":"This sentence is not part of the passage and does not relate to trails, visitors, or signs."},"",{"choice":"The passage says every reader already knew about nature trail.","category":"unsupported claim","reason":"The passage does not state that readers already know about the trail; it provides specific examples of what rangers added for visitors."},{"choice":"The title names the topic but gives no proof.","category":"meta-commentary error","reason":"This is a statement about titles rather than a sentence from the text that proves the information about the trail signs."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":105,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0106","version":3,"contentHash":"sha256:048b44970761e93115d5e393fb4b7afee47670dc87556c360cf771d2192667e8","question":"Read the passage. Grade 4 developing passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. These details show that students used careful daily routines to help a garden grow.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["The passage says every reader already knew about school garden.","The art room displayed clay bowls near the window.","They recorded how tall the seedlings grew.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting evidence must be a direct fact or action from the text that proves your main point is true.","example":"Point: The dog was hungry. Supporting evidence: The dog barked and nudged his empty bowl with his nose.","strategyClue":"Highlight the claim in the question, then underline every sentence in the passage that mentions an action the students performed. Select the action that shows the students looking at or tracking the plants.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. This sentence directly describes the students taking notes and measuring the plants, which provides evidence of them using observations to care for their garden.","incorrect":[{"choice":"The passage says every reader already knew about school garden.","category":"unsupported claim","reason":"This statement is not found in the text and does not provide any evidence that students were observing or measuring their plants."},{"choice":"The art room displayed clay bowls near the window.","category":"irrelevant information","reason":"Even if this were in the story, clay bowls in an art room have nothing to do with the students' work in the garden."},"",{"choice":"The title names the topic but gives no proof.","category":"misunderstanding evidence","reason":"A title is just a heading; it does not contain the specific actions of the students needed to support the claim about observations."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":106,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0107","version":3,"contentHash":"sha256:73acfc7c74e0b8874abedf8cf9ff9450f9d035a0fa6b91922cfd467d5b682040","question":"Read the passage. Grade 4 developing passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. These details show that student volunteers organized books and labels to make the library easier to use.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["The title names the topic but gives no proof.","The cafeteria served tomato soup on Thursday.","The passage says every reader already knew about library helpers.","They sorted returned books by call number before placing them on shelves."],"correct":3,"studyAid":{"definition":"Supporting evidence is a specific fact or detail from the text that proves your main idea is correct.","example":"Main idea: The park is fun. Evidence: There is a tall slide and a colorful sandbox.","strategyClue":"Ask yourself, 'Which sentence describes a specific action the volunteers took to solve a problem related to finding things?' Look for keywords like 'sorted' or 'arranged' that relate to organization.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This detail directly explains how books are organized so that readers can locate them quickly using the library's specific numbering system.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"Irrelevant logical connection","reason":"A title acts as a heading rather than a supporting detail. It does not provide the specific actions needed to show how library efficiency improved."},{"choice":"The cafeteria served tomato soup on Thursday.","category":"Off-topic information","reason":"This information is unrelated to the library or the volunteers' tasks. To be strong evidence, a detail must clearly connect to the main idea of library efficiency."},{"choice":"The passage says every reader already knew about library helpers.","category":"Unsupported claim","reason":"This statement is not found in the text and does not explain how books are arranged for better access. Strong evidence must come directly from the passage facts."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":107,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0108","version":3,"contentHash":"sha256:6001ca0604ab87140492368e5552b4e6313ec5a70984bdbd5f7d675d9f1aa0c4","question":"Read the passage. Grade 4 developing passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. These details show that a science club collected and reused rainwater to care for plants.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["Members used the stored water on dry afternoons instead of turning on the hose.","A soccer team practiced corner kicks after school.","The passage says every reader already knew about rain barrel.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To find evidence that supports an idea, look for sentences that describe the specific actions or reasons mentioned in that idea.","example":"Idea: The dog was helpful. Supporting sentence: The dog fetched the newspaper every morning.","strategyClue":"Highlight the key action mentioned in the idea you are supporting. Then, read each sentence and ask, 'Does this sentence show this specific action happening?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence directly shows the action of reusing rainwater as an alternative to using the hose, which supports the idea that the club used the water to care for plants.","incorrect":["",{"choice":"A soccer team practiced corner kicks after school.","category":"irrelevant information","reason":"This sentence is about a sports team, not the science club or rainwater, so it provides no support for the main idea."},{"choice":"The passage says every reader already knew about rain barrel.","category":"unsupported claim","reason":"This statement is not found in the text and does not explain how the club used water; it does not support the topic."},{"choice":"The title names the topic but gives no proof.","category":"not a detail","reason":"A title is just a label for the passage. To support an idea, you need specific evidence of an action taken by the club."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":108,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0109","version":3,"contentHash":"sha256:3891ef12e97fbe92b6b265e343ff7fe225ee0eeca099264a5e1a8839db18391b","question":"Read the passage. Grade 4 developing passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. These details show that student reporters gathered facts and published school news.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["The playground slide was painted blue over spring break.","They interviewed teachers, wrote short articles, and checked facts before printing.","The passage says every reader already knew about class newspaper.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence for an idea, look for actions or statements in the text that directly show that idea in action.","example":"Idea: 'The gardener worked hard.' Evidence: 'He pulled every weed and watered the flowers daily.'","strategyClue":"Focus on the specific goal mentioned in the question—in this case, 'accuracy'—and look for words related to checking, verifying, or careful preparation.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. This sentence directly describes the process of gathering information and verifying details, which is the definition of making a newspaper accurate.","incorrect":[{"choice":"The playground slide was painted blue over spring break.","category":"irrelevant information","reason":"This detail describes school property and has nothing to do with the newspaper or the reporters' work habits."},"",{"choice":"The passage says every reader already knew about class newspaper.","category":"unsupported claim","reason":"The passage never states this, and even if it did, a reader knowing about the paper does not prove that the reporters worked to make the content accurate."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title provides the subject of the text, but it does not contain the specific actions that prove the reporters were careful or accurate."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":109,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0110","version":3,"contentHash":"sha256:382065d830eb068abcc2e8402ee9220fd9e584bf7bab384400bc2d798cecc701","question":"Read the passage. Grade 4 developing passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. These details show that families cleaned litter from the beach and encouraged visitors to keep it clean.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["The passage says every reader already knew about beach cleanup.","The town band played a concert in the park.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting details are the specific facts, examples, or evidence provided in a text to prove that a main idea or conclusion is true.","example":"Main Idea: The dog was well-trained. Supporting Detail: He sat, stayed, and rolled over on command.","strategyClue":"Look for the sentence that lists concrete evidence or specific actions that directly prove the cleanup actually happened.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides specific, factual evidence of the cleanup actions described in the passage.","incorrect":[{"choice":"The passage says every reader already knew about beach cleanup.","category":"not in text","reason":"The passage never states that readers already knew about the cleanup; it describes the actual events that took place on the beach."},{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This information is not mentioned in the passage and does not support the claim that the beach was cleaned."},"",{"choice":"The title names the topic but gives no proof.","category":"meta-commentary error","reason":"This is a statement about a title, not a sentence from the passage, and it fails to provide any evidence regarding the cleanup efforts."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":110,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0111","version":3,"contentHash":"sha256:ac18f17fa5bcfc699857e052a96b92dfb1cca48f342c6874d9da9db042ff8d59","question":"Read the passage. Grade 4 developing passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. These details show that a safety officer taught students important bike safety habits.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["The title names the topic but gives no proof.","The school choir rehearsed a song about the moon.","The passage says every reader already knew about bike safety.","She showed how helmets should sit flat and snug on a rider's head."],"correct":3,"studyAid":{"definition":"Evidence is a specific detail from a text that directly proves or supports a statement or claim you are making.","example":"Claim: Dogs are helpful. Evidence: Many dogs are trained to help people find lost items.","strategyClue":"Highlight the keywords in the claim statement (e.g., 'helmet' and 'fit'). Search the text for sentences that contain those exact keywords or synonyms to find the supporting evidence.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence specifically describes how a helmet should fit, which directly supports the claim about correct helmet fitment for protection.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"Titles often introduce a topic, but they do not contain the specific facts or 'evidence' required to prove a statement about safety gear."},{"choice":"The school choir rehearsed a song about the moon.","category":"off-topic information","reason":"This information is about music and the moon, which has no connection to bike safety or how a helmet should fit."},{"choice":"The passage says every reader already knew about bike safety.","category":"unsupported claim","reason":"The passage never mentions what the readers already know; it focuses on what the officer taught the students."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":111,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0112","version":3,"contentHash":"sha256:7f4a403fbed50b7ef0841490c1c6d416d909dad05f30fab8a4d1218297218493","question":"Read the passage. Grade 4 developing passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. These details show that transportation planners improved bus service so people could reach useful places.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["The new route stopped near the clinic, grocery store, and community center.","A bakery sold cinnamon rolls before sunrise.","The passage says every reader already knew about city buses.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"A supporting detail is a piece of information or an example from the text that proves the main idea is true.","example":"Main Idea: My dog is helpful. Supporting Detail: He carries the newspaper to the door every morning.","strategyClue":"Look for the sentence that lists specific places where people go in their daily lives, as these locations help confirm that a service is useful to the community.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence provides specific examples of destinations that people need to visit, directly supporting the idea that the route serves community needs.","incorrect":["",{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"This sentence describes a bakery, not bus service. It does not provide any evidence about transportation or community needs."},{"choice":"The passage says every reader already knew about city buses.","category":"unsupported claim","reason":"This statement is not found in the text and does not offer any evidence to support the idea of serving community needs."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"This option discusses the title rather than providing a fact from the passage that proves the bus route is useful to the community."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":112,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0113","version":3,"contentHash":"sha256:f6e4924f70d17dc80686a914c7a2664f853e2053bf96eaa09a370a566a1e9be4","question":"Read the passage. Grade 4 developing passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. These details show that actors and crew members cooperated to get a play ready.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["A math poster showed different kinds of triangles.","Actors practiced lines while stage crew members painted scenery and tested lights.","The passage says every reader already knew about school play.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find the strongest evidence, look for the text that directly identifies multiple roles or tasks that must happen at the same time to achieve a specific result.","example":"If the claim is 'The garden needs many tools,' look for a sentence listing a shovel, rake, and hose, rather than a sentence describing only the flowers.","strategyClue":"Highlight the claim, then scan each option to see which one explicitly lists tasks that are NOT acting, such as building, painting, or technical work.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence explicitly mentions the work of the stage crew, proving that people other than actors were necessary for the production.","incorrect":[{"choice":"A math poster showed different kinds of triangles.","category":"irrelevant information","reason":"This information is not found in the passage and does not relate to the requirements of a theater production."},"",{"choice":"The passage says every reader already knew about school play.","category":"unsupported claim","reason":"The passage does not mention what the readers know; this choice makes an assumption not backed by the text."},{"choice":"The title names the topic but gives no proof.","category":"missing evidentiary support","reason":"While titles can provide context, they do not offer the specific details needed to prove that a production requires more than just acting."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":113,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0114","version":3,"contentHash":"sha256:736d175a23a414b31e36b94efd8a626d7c9dded3145d42983e80d349d9da1e65","question":"Read the passage. Grade 4 developing passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. These details show that cafeteria food scraps were collected and turned into compost for flowers.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["The passage says every reader already knew about compost bin.","A new scoreboard was installed in the gym.","After several weeks, the dark compost was mixed into flower beds.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To find evidence in a text, look for specific details that directly connect back to the main point or claim made in the prompt.","example":"Claim: Dogs are helpful pets. Evidence: A dog helped the boy find his lost keys.","strategyClue":"Identify the key topic in the goal sentence (e.g., 'useful' or 'not thrown away'), then scan each choice to see which one describes an action or process that matches that topic.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence shows the food scraps being repurposed into soil for the garden, which directly supports the idea that scraps are useful rather than trash.","incorrect":[{"choice":"The passage says every reader already knew about compost bin.","category":"Unsupported claim","reason":"The passage never states that all readers have prior knowledge about composting; this is not a fact found within the text."},{"choice":"A new scoreboard was installed in the gym.","category":"Irrelevant detail","reason":"This information about a gym scoreboard does not relate to food scraps, composting, or recycling at all."},"",{"choice":"The title names the topic but gives no proof.","category":"Meta-commentary error","reason":"This statement describes the title, but does not provide evidence from the text to support the claim about turning scraps into useful items."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":114,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0115","version":3,"contentHash":"sha256:5a773c0f298272ebca5813d08026751a866db2454c0ba92c179e6adfafafeccb","question":"Read the passage. Grade 4 developing passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. These details show that science students recorded weather measurements and used them to find patterns.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["The title names the topic but gives no proof.","The music teacher tuned a violin before class.","The passage says every reader already knew about weather station.","They measured rainfall, wind direction, temperature, and cloud cover every day."],"correct":3,"studyAid":{"definition":"To find evidence in a passage, look for the sentence that lists specific facts, details, or actions that directly prove the main claim.","example":"Claim: 'The garden was healthy.' Evidence: 'Red tomatoes, bright yellow sunflowers, and green beans grew in the soil.'","strategyClue":"Look for the sentence that contains a list of specific examples or measurements, then check if those items count as 'more than one' type of evidence.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. This sentence lists four distinct types of data the students collected, which directly supports the idea that they gathered multiple kinds of weather evidence.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"Titles often introduce a topic, but they do not contain the specific data or 'evidence' required to prove a statement about what the students actually did."},{"choice":"The music teacher tuned a violin before class.","category":"off-topic content","reason":"This information is completely unrelated to the science students or the weather measurements mentioned in the passage."},{"choice":"The passage says every reader already knew about weather station.","category":"unsupported claim","reason":"This statement is not found in the text, and even if it were, it does not provide evidence about the specific actions or measurements taken by the students."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":115,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0116","version":3,"contentHash":"sha256:987020764fe9e1944f8649371bfd759792c0be7b18eff12e193e4912465f1a61","question":"Read the passage. Grade 4 developing passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. These details show that a recycling team used bins and reminders to reduce paper waste.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["By winter break, the school ordered fewer boxes of printer paper.","The nurse checked the first-aid supplies after lunch.","The passage says every reader already knew about recycling team.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To find evidence for a claim, look for a sentence that provides a concrete fact, statistic, or result that proves the idea is true.","example":"Claim: The garden grew well. Evidence: We harvested ten pounds of tomatoes.","strategyClue":"Look for a sentence that describes a specific result or change caused by the recycling team's actions. The correct sentence will show a difference between 'before' and 'after' the plan.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence provides direct evidence of a decrease in paper usage, which demonstrates that the team's plan was successful in changing school habits.","incorrect":["",{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence discusses a different topic (first-aid supplies) and does not mention paper usage or the recycling team."},{"choice":"The passage says every reader already knew about recycling team.","category":"unsupported claim","reason":"The passage does not state that all readers knew about the team; furthermore, this claim does not explain or prove the change in paper usage."},{"choice":"The title names the topic but gives no proof.","category":"incorrect text analysis","reason":"Titles usually introduce a subject, but they do not serve as proof or evidence for the specific results described in the passage."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":116,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0117","version":3,"contentHash":"sha256:4146c3c64a83b3d561feb1e6d7e89d9d6151400208b0749f8e135063f8ae6378","question":"Read the passage. Grade 4 developing passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. These details show that museum workers created an exhibit that helped visitors learn local history.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["A rainstorm delayed the baseball game.","Visitors could press buttons to hear recordings of elders telling memories.","The passage says every reader already knew about museum exhibit.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports or proves your answer.","example":"Question: 'How was the room messy?' Evidence: 'Clothes were piled on the chair and books were scattered on the floor.'","strategyClue":"Break your answer into two parts—'objects' and 'personal stories'—and find the specific sentence in the text that mentions both or confirms the presence of these two distinct categories.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This choice provides direct evidence for the 'personal stories' part of the statement, as elders sharing memories are stories, and the buttons/recordings demonstrate how visitors interact with them.","incorrect":[{"choice":"A rainstorm delayed the baseball game.","category":"irrelevant information","reason":"This sentence is not mentioned in the passage and does not relate to the museum exhibit at all."},"",{"choice":"The passage says every reader already knew about museum exhibit.","category":"unsupported claim","reason":"The passage does not state that readers already knew about the exhibit; this choice does not provide evidence for objects or personal stories."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"While a title might name a topic, it does not act as evidence for specific details contained within the exhibit like objects or stories."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":117,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0118","version":3,"contentHash":"sha256:2509c71af659b384bda6ab6fcd283a375d1ee28bf36b6312c1aff469448525b7","question":"Read the passage. Grade 4 developing passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. These details show that club members tested a robot, changed its code, and used notes to improve it.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["The passage says every reader already knew about robotics club.","The principal announced picture day over the speaker.","Each time the robot missed a turn, members adjusted the code and tested again.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting evidence is a sentence from the text that proves or explains a specific idea or claim.","example":"Claim: The weather was bad. Evidence: 'Rain poured down all day, and the wind blew over our patio furniture.'","strategyClue":"Look for the specific words in the claim—in this case 'mistakes' and 'information'—and find the sentence in the text that describes that exact action happening.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence directly describes the club members using a 'mistake' (missing a turn) as 'information' (data to help them adjust the code and test again).","incorrect":[{"choice":"The passage says every reader already knew about robotics club.","category":"Unsupported by text","reason":"This information is not present in the passage, and it does not explain how the club uses mistakes to improve their robot."},{"choice":"The principal announced picture day over the speaker.","category":"Irrelevant information","reason":"This sentence describes an event unrelated to the robotics club or the process of testing and improving a robot."},"",{"choice":"The title names the topic but gives no proof.","category":"Meta-analysis error","reason":"This describes a general feature of titles rather than providing a specific example of how the club used their experimental failures to learn."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":118,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0119","version":3,"contentHash":"sha256:1dec0a6864bc860323d179fb2e79b157023739beccac9db9aceb3f020ca1a375","question":"Read the passage. Grade 4 developing passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. These details show that school leaders made breakfast easier for busy students to get.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["The title names the topic but gives no proof.","The science lab received new magnifying glasses.","The passage says every reader already knew about school breakfast.","Students who arrived close to the bell could still choose a quick meal."],"correct":3,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly proves the main point or answers the specific question being asked.","example":"If the claim is 'The dog is messy', evidence could be 'The dog left muddy paw prints on the carpet' rather than 'The dog is a golden retriever'.","strategyClue":"Highlight the key words in the question, such as 'little time'. Then, scan the passage for a sentence that mentions a time-related challenge and how the cart solves that specific problem.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This detail directly supports the idea of having little time, as it shows the school made the service accessible even to those rushing to get to class.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"This is a general statement about titles, but it does not provide any specific evidence from the text that explains why the cart helps students who are short on time."},{"choice":"The science lab received new magnifying glasses.","category":"not in text","reason":"This information is not mentioned anywhere in the passage provided. Always select evidence that actually appears in the text."},{"choice":"The passage says every reader already knew about school breakfast.","category":"inaccurate claim","reason":"The passage never mentions what the readers already knew. Even if it did, knowing about breakfast does not explain how the cart helps students with little time."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":119,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0120","version":3,"contentHash":"sha256:daf7225825acbe27a4c4e17cc4e7a43a07561da499ca730ce29c3eea6095efa0","question":"Read the passage. Grade 4 developing passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. These details show that park rangers marked a trail so visitors could navigate and learn.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["They added arrows, distance signs, and small plaques naming common trees.","The post office closed early on Saturday.","The passage says every reader already knew about nature trail.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support an idea, you must find specific evidence in the text that directly matches the keywords or actions described in the main point.","example":"Main point: 'The party was loud.' Evidence: 'Music blasted from the speakers and guests shouted to be heard.'","strategyClue":"Highlight the two key things you are looking for in the passage: 'directions' and 'information.' Read each sentence and ask yourself, 'Does this sentence show both of these things?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. This sentence directly lists items that provide both 'directions' (arrows and distance signs) and 'information' (plaques naming trees), supporting the idea that the rangers helped visitors navigate and learn.","incorrect":["",{"choice":"The post office closed early on Saturday.","category":"irrelevant information","reason":"This sentence is not part of the passage and mentions a post office, which has nothing to do with the park rangers or the nature trail."},{"choice":"The passage says every reader already knew about nature trail.","category":"unsupported claim","reason":"The passage does not state that readers already know about the trail. Always look for evidence found directly in the text provided."},{"choice":"The title names the topic but gives no proof.","category":"meta-textual error","reason":"While a title names a topic, this sentence does not provide any specific evidence from the text about what the rangers actually added to the trail."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":120,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0121","version":3,"contentHash":"sha256:59cf26ccb931bf82dc2b975e24342a5eece7c1a2d8be441db09efbbcad0565ee","question":"Read the passage. Grade 4 challenge passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. Because the passage connects actions with results, readers can see why daily care helped the school garden grow well.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["The art room displayed clay bowls near the window.","They recorded how tall the seedlings grew.","The passage says every reader already knew about school garden.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence for a claim, look for sentences that show an action or detail directly related to the idea being discussed.","example":"Claim: The dog is hungry. Evidence: The dog whined at the food bowl and wagged its tail when the bag opened.","strategyClue":"Identify the key words in the claim ('observations' and 'care'), then search the passage for a specific action that shows the students paying attention to the plants' progress.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. This sentence provides evidence that students used observations, as tracking growth is a method of observing and measuring the health of the plants.","incorrect":[{"choice":"The art room displayed clay bowls near the window.","category":"irrelevant information","reason":"This sentence describes an art room and clay bowls, which has nothing to do with garden plants or student observations."},"",{"choice":"The passage says every reader already knew about school garden.","category":"unsupported claim","reason":"The passage does not state this, and it does not show how students used observations to care for their plants."},{"choice":"The title names the topic but gives no proof.","category":"meta-analysis error","reason":"This refers to the structure of a title rather than the specific actions students took in the garden to monitor plant growth."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":121,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0122","version":3,"contentHash":"sha256:58e40f283e22b8c8576219ff05574c7cb7a2375cca8a4bcae5097a81b8d2c09d","question":"Read the passage. Grade 4 challenge passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. Because the passage connects actions with results, readers can see why student helpers organized the library so readers could find books faster.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["The passage says every reader already knew about library helpers.","The cafeteria served tomato soup on Thursday.","They sorted returned books by call number before placing them on shelves.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To find the strongest evidence, look for a specific action in the text that directly proves the claim or explains 'how' something was achieved.","example":"Claim: The garden is healthy. Evidence: The plants are green and have grown six inches this month.","strategyClue":"Look for a sentence that describes a specific method or step taken by the volunteers. Ask yourself: 'Does this action explain the result of finding books more easily?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This detail directly explains the system used to organize books, which allows readers to locate specific materials quickly based on their call numbers.","incorrect":[{"choice":"The passage says every reader already knew about library helpers.","category":"unsupported claim","reason":"The passage does not state this information. Even if it were true, knowing about helpers doesn't prove that readers can find materials more efficiently."},{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This sentence mentions an event that has nothing to do with the library or how books are organized, so it provides no evidence for the claim."},"",{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"The title describes what the passage is about, but it is not a detail or action that proves the efficiency of the volunteers' work."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":122,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0123","version":3,"contentHash":"sha256:5b319103291999189c4c43f765e3982905a91f694c7d58d5770cce8295392e2a","question":"Read the passage. Grade 4 challenge passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. Because the passage connects actions with results, readers can see why a rain barrel helped the club save water for plants.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["The title names the topic but gives no proof.","A soccer team practiced corner kicks after school.","The passage says every reader already knew about rain barrel.","Members used the stored water on dry afternoons instead of turning on the hose."],"correct":3,"studyAid":{"definition":"To find evidence in a text, look for sentences that provide a concrete example or result related to your specific question.","example":"Question: How do we know the dog was happy? Evidence: The dog wagged its tail when the owner walked through the door.","strategyClue":"Look for the sentence that mentions the 'hose' or the act of choosing one water source over another. Ask yourself: 'Which sentence shows the club actually saving the water they collected?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence directly describes the club choosing to use rainwater as an alternative to using the hose, which provides evidence that the barrel reduced their need for outside water.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not a sentence","reason":"This is a statement about a title rather than a sentence from the passage that demonstrates the club's specific actions or results."},{"choice":"A soccer team practiced corner kicks after school.","category":"irrelevant information","reason":"This sentence describes a completely different activity involving sports, which does not relate to the science club or the use of rainwater."},{"choice":"The passage says every reader already knew about rain barrel.","category":"unsupported claim","reason":"The passage does not state that readers already knew this information, and this sentence does not explain how the rain barrel helped save water."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":123,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0124","version":3,"contentHash":"sha256:6e6cd827584b27a207df6351b44490103b6e3a1deadf6816dc3f4d03e531b0d8","question":"Read the passage. Grade 4 challenge passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. Because the passage connects actions with results, readers can see why the class newspaper gave students a careful way to share school news.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["They interviewed teachers, wrote short articles, and checked facts before printing.","The playground slide was painted blue over spring break.","The passage says every reader already knew about class newspaper.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To find evidence for a claim, look for specific actions or descriptions in the text that directly support or explain that claim.","example":"Claim: The cat was hungry. Evidence: The cat stood by its bowl and meowed loudly.","strategyClue":"Look for words that relate to accuracy, such as 'checked,' 'facts,' 'correct,' or 'verified,' and identify which sentence explains how the reporters worked.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. This sentence lists specific actions the reporters took, such as 'checking facts,' which is a direct method used to ensure information is correct and accurate.","incorrect":["",{"choice":"The playground slide was painted blue over spring break.","category":"irrelevant detail","reason":"This sentence describes playground equipment and has nothing to do with the students' work or the accuracy of the newspaper."},{"choice":"The passage says every reader already knew about class newspaper.","category":"unsupported claim","reason":"The passage does not state this, and it would not prove the reporters worked to make the articles accurate."},{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"A title might show what the newspaper is about, but it does not provide the specific actions taken by the reporters to ensure their work was accurate."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":124,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0125","version":3,"contentHash":"sha256:6b1bc815268f9c78fdb583dd10a8fdc79123bbab1aedb1c8da106700eea954cd","question":"Read the passage. Grade 4 challenge passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. Because the passage connects actions with results, readers can see why the cleanup protected the beach by removing harmful litter.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["The town band played a concert in the park.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The passage says every reader already knew about beach cleanup.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To support an idea, find a sentence that provides concrete evidence, facts, or actions that directly prove the statement is true.","example":"Claim: The weather was cold. Evidence: The water in the birdbath turned into a solid block of ice.","strategyClue":"Look for the specific words in the claim—like 'litter' or 'wildlife'—and scan the text for a sentence that describes the physical removal of those items.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides specific examples of the harmful litter that was removed from the environment, which directly explains how the cleanup made the beach safer for wildlife.","incorrect":[{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This sentence describes a completely different event and does not mention litter, the beach, or any cleanup activities."},"",{"choice":"The passage says every reader already knew about beach cleanup.","category":"unsupported claim","reason":"This statement is not found in the passage and does not provide any evidence regarding the safety of wildlife."},{"choice":"The title names the topic but gives no proof.","category":"misidentifying evidence","reason":"A title might introduce a topic, but it does not provide the specific details or actions needed to prove that the environment was made safer."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":125,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0126","version":3,"contentHash":"sha256:eef4a1962d6e4ac7eba9aa7766eec60c0ef110087f95d66f0c3371c87287afaa","question":"Read the passage. Grade 4 challenge passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. Because the passage connects actions with results, readers can see why bike riders can prevent injuries by following safety rules.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["The passage says every reader already knew about bike safety.","The school choir rehearsed a song about the moon.","She showed how helmets should sit flat and snug on a rider's head.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports a claim or statement you are trying to prove.","example":"Claim: Dogs are active pets. Evidence: They enjoy playing fetch and running in the yard.","strategyClue":"Highlight the claim you are testing, then scan the passage to find the specific sentence that explains the 'how' or 'why' behind that claim.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence provides direct evidence regarding the physical requirement of a helmet for it to be effective and safe.","incorrect":[{"choice":"The passage says every reader already knew about bike safety.","category":"not supported by text","reason":"The passage does not state that readers already know about safety; rather, it explains the safety rules through the officer's lesson."},{"choice":"The school choir rehearsed a song about the moon.","category":"irrelevant information","reason":"This detail is completely unrelated to bike safety or how to wear a helmet, so it cannot serve as evidence for your answer."},"",{"choice":"The title names the topic but gives no proof.","category":"not textual evidence","reason":"A title might introduce a topic, but it does not provide the specific factual details needed to support the claim about how a helmet should fit."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":126,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0127","version":3,"contentHash":"sha256:79d9f691fc6807e6a9381be70d604fcf781d7872eff01efa83adef395d3e991c","question":"Read the passage. Grade 4 challenge passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. Because the passage connects actions with results, readers can see why new bus routes made important places easier to reach.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["The title names the topic but gives no proof.","A bakery sold cinnamon rolls before sunrise.","The passage says every reader already knew about city buses.","The new route stopped near the clinic, grocery store, and community center."],"correct":3,"studyAid":{"definition":"A supporting sentence provides evidence or specific details that prove the truth of a main idea or claim.","example":"Claim: The park is fun. Support: There is a tall slide, a jungle gym, and a basketball court.","strategyClue":"Identify the key terms in the claim—in this case, 'served community needs'—and look for a sentence in the text that mentions places where a community gathers or receives services.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence lists essential locations that people visit for daily necessities, which directly proves how the bus route addresses community needs.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not in text","reason":"This is a statement about a title, which is not present in the provided passage, and it does not provide any evidence about bus routes serving needs."},{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"This sentence is not found in the passage and does not mention bus routes or community needs at all."},{"choice":"The passage says every reader already knew about city buses.","category":"misinterpretation of text","reason":"The passage does not state that readers already knew about buses, and this claim does not support the idea that the route served specific community needs."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":127,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0128","version":3,"contentHash":"sha256:de7e4db6c72bcca1178331e9dc46d214706cee4c3735279a00b09e59ad51bebb","question":"Read the passage. Grade 4 challenge passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. Because the passage connects actions with results, readers can see why many students worked together to prepare the school play.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["Actors practiced lines while stage crew members painted scenery and tested lights.","A math poster showed different kinds of triangles.","The passage says every reader already knew about school play.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Supporting evidence is a specific fact, detail, or quote from the text that directly proves a statement is true.","example":"Statement: 'The dog was hungry.' Evidence: 'The dog whined and pushed its empty bowl toward its owner.'","strategyClue":"Look for the sentence that lists different roles or tasks happening at the same time. If a detail only mentions actors, it cannot prove that the production required more than acting.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence explicitly mentions multiple jobs—acting, painting, and testing lights—which proves the production involved more than just performing lines.","incorrect":["",{"choice":"A math poster showed different kinds of triangles.","category":"Irrelevant information","reason":"This detail is not mentioned in the passage and has nothing to do with preparing for a school play."},{"choice":"The passage says every reader already knew about school play.","category":"Unsupported claim","reason":"The passage does not state that the readers already knew about the play; it focuses on the actions taken by the students to prepare it."},{"choice":"The title names the topic but gives no proof.","category":"Missing evidence","reason":"A title might introduce a topic, but the evidence for 'more than acting' must be a specific action or role found within the text of the passage."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":128,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0129","version":3,"contentHash":"sha256:4c190469144f743cedd77cecc160b620602f389ed68a0f864e3fc6fe174e19e2","question":"Read the passage. Grade 4 challenge passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. Because the passage connects actions with results, readers can see why composting changed cafeteria scraps into useful soil material.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["A new scoreboard was installed in the gym.","After several weeks, the dark compost was mixed into flower beds.","The passage says every reader already knew about compost bin.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence that supports an idea, look for the sentence in the text that directly describes the action or result mentioned in your goal.","example":"Idea: The dog was helpful. Sentence: The dog carried the groceries into the kitchen.","strategyClue":"Identify the key words in the goal statement—like 'useful' and 'scraps'—then scan the passage for sentences that describe these specific things interacting or changing.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence explicitly shows the food scraps being transformed and put to use in the garden, confirming that they are no longer just trash.","incorrect":[{"choice":"A new scoreboard was installed in the gym.","category":"irrelevant information","reason":"This sentence mentions a gym and a scoreboard, which has nothing to do with food scraps or turning waste into soil."},"",{"choice":"The passage says every reader already knew about compost bin.","category":"not in text","reason":"This statement is not found in the passage, and even if it were, it does not provide evidence that scraps become useful soil."},{"choice":"The title names the topic but gives no proof.","category":"meta-commentary error","reason":"This describes a title rather than pointing to a specific action within the story that shows the scraps being used for a productive purpose."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":129,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0130","version":3,"contentHash":"sha256:d6e66c01b84aaf10ae264a62d50807a9f369c33c5f104b0316d86ea67d91960e","question":"Read the passage. Grade 4 challenge passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. Because the passage connects actions with results, readers can see why students collected weather data to notice local patterns.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["The passage says every reader already knew about weather station.","The music teacher tuned a violin before class.","They measured rainfall, wind direction, temperature, and cloud cover every day.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To support an answer with evidence, you must find the exact part of the text that directly explains or lists the facts related to the question.","example":"Question: 'How did the cat get out?' Evidence: 'The cat squeezed through the open window.'","strategyClue":"Look for the specific sentence in the passage that contains a list or a detailed description of the students' actions, then check if that list includes more than one item.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. This sentence lists four distinct types of data points, which clearly proves that the students collected multiple kinds of weather evidence.","incorrect":[{"choice":"The passage says every reader already knew about weather station.","category":"irrelevant information","reason":"This statement is not supported by the text and does not provide any evidence about what the students actually collected."},{"choice":"The music teacher tuned a violin before class.","category":"off-topic sentence","reason":"This sentence is about music and is not part of the passage, so it cannot be used as evidence for a science experiment."},"",{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title might introduce a topic, but it does not list specific measurements or actions taken by the students to show they collected multiple types of data."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":130,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0131","version":3,"contentHash":"sha256:3b902d24e5d0e06266bfc672ce3ba6d66806f67f6cbe02479d08357f0794b381","question":"Read the passage. Grade 4 challenge passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. Because the passage connects actions with results, readers can see why the recycling team helped the school waste less paper.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["The title names the topic but gives no proof.","The nurse checked the first-aid supplies after lunch.","The passage says every reader already knew about recycling team.","By winter break, the school ordered fewer boxes of printer paper."],"correct":3,"studyAid":{"definition":"To support an idea, find evidence in the text that directly shows the result or consequence of an action described.","example":"Claim: The garden grew well. Support: We picked ten big tomatoes yesterday.","strategyClue":"Look for a sentence that describes a measurable change or a specific outcome related to the school's actions with paper.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence shows a direct change in the amount of paper used, which provides clear evidence that the recycling plan was effective.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"This statement is an opinion about a title, not a sentence from the passage that demonstrates a change in paper usage."},{"choice":"The nurse checked the first-aid supplies after lunch.","category":"unrelated content","reason":"This sentence is not in the passage and does not relate to the topic of paper usage or recycling."},{"choice":"The passage says every reader already knew about recycling team.","category":"factually incorrect claim","reason":"The passage does not state that readers already knew about the team, and this sentence does not provide evidence about how much paper was used."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":131,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0132","version":3,"contentHash":"sha256:f3af5f8c91b65c1a62034d14388f62781a895661da47277ef442630824575fed","question":"Read the passage. Grade 4 challenge passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. Because the passage connects actions with results, readers can see why the exhibit used artifacts and voices to teach local history.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["Visitors could press buttons to hear recordings of elders telling memories.","A rainstorm delayed the baseball game.","The passage says every reader already knew about museum exhibit.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Strong evidence must directly support the claim being made by providing specific facts, quotes, or details from the text.","example":"Claim: The dog is friendly. Evidence: The dog wagged its tail and licked my hand when I walked in.","strategyClue":"Look for the specific words in the claim—'objects' and 'personal stories'—and find the sentences that describe items you can see and things you can hear.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This sentence provides evidence for 'personal stories,' while the previous sentence about tools, photographs, and letters provides evidence for 'objects.'","incorrect":["",{"choice":"A rainstorm delayed the baseball game.","category":"irrelevant information","reason":"This detail is completely unrelated to the museum exhibit or the topic of local history mentioned in the passage."},{"choice":"The passage says every reader already knew about museum exhibit.","category":"unsupported claim","reason":"The passage does not state that readers already knew about the exhibit; this information is not found in the text provided."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title might introduce a topic, but it does not provide the specific factual details needed to prove that the exhibit contained both objects and stories."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":132,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0133","version":3,"contentHash":"sha256:4dbcfdc84793ae733c86fb2e19df3e123546ba855ca7a13de1046c5f7f361f5e","question":"Read the passage. Grade 4 challenge passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. Because the passage connects actions with results, readers can see why testing and revising helped the robotics club improve its robot.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["The principal announced picture day over the speaker.","Each time the robot missed a turn, members adjusted the code and tested again.","The passage says every reader already knew about robotics club.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting evidence consists of specific details, facts, or actions from the text that prove a claim or conclusion is true.","example":"Claim: The dog was hungry. Evidence: The dog nudged his empty bowl and barked at the kitchen door.","strategyClue":"Search for sentences that describe a 'cause and effect' relationship, where an error is identified and immediately followed by a corrective action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence shows that the members treated a mistake (the robot missing a turn) as a chance to learn and make a specific adjustment.","incorrect":[{"choice":"The principal announced picture day over the speaker.","category":"irrelevant information","reason":"This sentence is about a school event and has nothing to do with the robotics club or the process of fixing mistakes."},"",{"choice":"The passage says every reader already knew about robotics club.","category":"unsupported by text","reason":"This claim does not appear in the text and does not show the club using mistakes as information to improve their robot."},{"choice":"The title names the topic but gives no proof.","category":"meta-commentary error","reason":"This sentence describes a title rather than providing evidence from the action-packed story about the robotics club."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":133,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0134","version":3,"contentHash":"sha256:b9d2eeb0e259170c7dd1dc193c6b216999f402848690babc7c5ec71b864ace3c","question":"Read the passage. Grade 4 challenge passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. Because the passage connects actions with results, readers can see why the breakfast cart helped more students start the day with food.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["The passage says every reader already knew about school breakfast.","The science lab received new magnifying glasses.","Students who arrived close to the bell could still choose a quick meal.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence must directly support the claim by providing specific facts, actions, or details from the text.","example":"Claim: The library is a quiet place. Evidence: 'Students sat at desks, silently reading their books.' (Correct) vs. 'The library has many books.' (Incorrect, doesn't mention quietness).","strategyClue":"Underline the key words in the claim ('little time', 'before class'). Search the passage for a sentence that describes a student's arrival time and how the cart accommodated that schedule.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This sentence shows that the cart served students with limited time, as they could grab food even when they were nearly late for class.","incorrect":[{"choice":"The passage says every reader already knew about school breakfast.","category":"not supported by text","reason":"The text does not mention the readers' prior knowledge, so this statement cannot act as evidence for the cart's design."},{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information","reason":"The science lab and magnifying glasses are not mentioned in the passage and do not relate to the breakfast cart or student time management."},"",{"choice":"The title names the topic but gives no proof.","category":"missing textual evidence","reason":"This choice ignores the actual sentences in the passage; look for a detail about student schedules or the speed of the breakfast service."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":134,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0135","version":3,"contentHash":"sha256:87ee6693d287aa65d0b2be6a1eb71c7d0125f4976d5385671126863f16178c5c","question":"Read the passage. Grade 4 challenge passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. Because the passage connects actions with results, readers can see why trail signs helped visitors move safely and learn about nature.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["The title names the topic but gives no proof.","The post office closed early on Saturday.","The passage says every reader already knew about nature trail.","They added arrows, distance signs, and small plaques naming common trees."],"correct":3,"studyAid":{"definition":"To support a main idea or conclusion, look for specific evidence or details in the text that directly match the points being made.","example":"Claim: The classroom was messy. Evidence: Papers were scattered on the floor and art supplies covered the tables.","strategyClue":"Break down the claim into two parts: 'directions' and 'information'. Look for a sentence in the passage that mentions specific objects serving these two distinct purposes.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. This sentence explicitly provides evidence for the claim by identifying specific trail features that provide both directions ('arrows') and information ('plaques naming common trees').","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not in text","reason":"This sentence does not appear in the passage, and the passage does not include a title. You must find evidence actually present in the text provided."},{"choice":"The post office closed early on Saturday.","category":"unrelated information","reason":"This information is not mentioned in the text and does not relate to trail signs, directions, or learning about nature."},{"choice":"The passage says every reader already knew about nature trail.","category":"misreading the text","reason":"The passage never makes this claim. Instead, it describes how the signs were added to help visitors learn about nature."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":135,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0136","version":3,"contentHash":"sha256:f13e781c48e2c0ef0f22fc1b57ba91df95c0c7df4ae7c08130ff1d130881a5b9","question":"Read the passage. Grade 5 foundation passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["They recorded how tall the seedlings grew.","The art room displayed clay bowls near the window.","The passage says every reader already knew about school garden.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support an idea, find a sentence that describes a specific action, detail, or fact that proves that idea is true.","example":"Idea: The puppy was energetic. Sentence: The puppy zoomed across the yard and chased the ball for an hour.","strategyClue":"Look for a sentence that describes a specific task the students performed. Ask yourself, 'Does this action show they were looking at or tracking the plants?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. Recording measurements is an act of observation, which directly supports the idea that students watched and documented the progress of their plants.","incorrect":["",{"choice":"The art room displayed clay bowls near the window.","category":"irrelevant information","reason":"This sentence describes art supplies, not the garden or the actions the students took to care for the plants."},{"choice":"The passage says every reader already knew about school garden.","category":"incorrect text evidence","reason":"The passage does not state that readers already know about the garden; therefore, this sentence cannot be used as proof for how the students cared for plants."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title acts as a label, not an action. Observations are actions that show what the students did, so a title is not evidence of their caretaking."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":136,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0137","version":3,"contentHash":"sha256:d718eb7e8eddc552d0ee8b3c52daef946267d3b261892976768156214f0f805e","question":"Read the passage. Grade 5 foundation passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["The cafeteria served tomato soup on Thursday.","They sorted returned books by call number before placing them on shelves.","The passage says every reader already knew about library helpers.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Strong evidence for a claim is a specific fact or detail from the text that directly explains or supports the main idea.","example":"Claim: The garden is messy. Evidence: There are weeds growing over the flowers and empty pots scattered on the grass.","strategyClue":"Ask yourself, 'Which sentence describes an action that specifically fixes a problem or improves a situation for a library reader?' Look for the connection between the action and the result of finding things.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. Organizing books by call number directly relates to how readers navigate the library, making it much faster to find specific materials.","incorrect":[{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This information does not appear in the passage and has nothing to do with library organization or helping readers find books."},"",{"choice":"The passage says every reader already knew about library helpers.","category":"misinterpreted passage content","reason":"The passage does not state that readers knew about the helpers; it focuses on the actions the volunteers took to organize the library."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"While titles can be helpful, they do not act as evidence; you need to look for specific actions within the text that explain how the volunteers helped."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":137,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0138","version":3,"contentHash":"sha256:f03854fc087eaef5ed9c6102fe075608e4b63db81c0e32c2d3070138c9131874","question":"Read the passage. Grade 5 foundation passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["The passage says every reader already knew about rain barrel.","A soccer team practiced corner kicks after school.","Members used the stored water on dry afternoons instead of turning on the hose.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To support an idea, find a sentence that provides direct evidence or proof for the claim being made.","example":"Claim: The cat was hungry. Supporting sentence: The cat meowed loudly and stared at his empty bowl.","strategyClue":"Look at the main claim in the question, then re-read the passage to find the specific action that proves the claim is true.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence directly shows that the rainwater replaced the need to use the hose, which supports the idea that the barrel reduced hose water use.","incorrect":[{"choice":"The passage says every reader already knew about rain barrel.","category":"Unsupported claim","reason":"The passage does not state that readers were already familiar with rain barrels; this is not evidence for why the barrel reduced water usage."},{"choice":"A soccer team practiced corner kicks after school.","category":"Irrelevant information","reason":"This sentence is not in the passage and has nothing to do with saving water or the rain barrel's purpose."},"",{"choice":"The title names the topic but gives no proof.","category":"Missing text evidence","reason":"The question asks for a sentence that proves the claim, and a title would not provide the specific actions taken by the club members."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":138,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0139","version":3,"contentHash":"sha256:36feb3382579425fdbfe71e195367bb437a75171d1284bb24ebbcdd4f936efe1","question":"Read the passage. Grade 5 foundation passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["The title names the topic but gives no proof.","The playground slide was painted blue over spring break.","The passage says every reader already knew about class newspaper.","They interviewed teachers, wrote short articles, and checked facts before printing."],"correct":3,"studyAid":{"definition":"Strong evidence is a specific piece of information from the text that directly proves a claim or answers a question.","example":"Claim: The cat was hungry. Evidence: The cat meowed loudly and stared at its empty food bowl.","strategyClue":"Look for verbs that describe careful actions like 'checking,' 'verifying,' or 'investigating' to find support for claims about accuracy.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. This sentence explicitly describes the steps the reporters took to verify their work, which directly supports the claim that they aimed for accuracy.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"This is not a detail from the passage; additionally, a title only identifies the subject and cannot provide evidence regarding the reporters' work habits."},{"choice":"The playground slide was painted blue over spring break.","category":"off-topic evidence","reason":"While this might be a fact, it has nothing to do with the newspaper or how the reporters gathered or checked their information."},{"choice":"The passage says every reader already knew about class newspaper.","category":"unsupported claim","reason":"The passage does not state this, and even if it did, a reader's prior knowledge does not provide evidence that the reporters themselves were working to be accurate."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":139,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0140","version":3,"contentHash":"sha256:890b30e300d91c29c7410d5025ec5e507ebefe31e4899c8a03e292cea5c756e0","question":"Read the passage. Grade 5 foundation passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The town band played a concert in the park.","The passage says every reader already knew about beach cleanup.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Supporting evidence consists of specific facts or details from the text that prove a claim is true.","example":"Claim: The garden is healthy. Evidence: The plants are green and growing tall.","strategyClue":"Search the text for actions that directly prevent harm to animals. Ask yourself, 'Which sentence shows us exactly what was removed from the beach to keep it safe?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides evidence of the cleanup action because removing harmful items like fishing line and plastic directly protects animals from injury or ingestion.","incorrect":["",{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This sentence describes a musical event that has no connection to the environment, wildlife, or the beach cleanup effort."},{"choice":"The passage says every reader already knew about beach cleanup.","category":"unsupported claim","reason":"This is a statement about the reader's knowledge, not a fact from the text that explains how wildlife is kept safer."},{"choice":"The title names the topic but gives no proof.","category":"missing textual evidence","reason":"A title might introduce a subject, but it does not contain the specific details or actions needed to prove the cleanup made the area safer."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":140,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0141","version":3,"contentHash":"sha256:b81b56f16e15109ebd43966a357d282a0084a27a1fec77f44f3a7f77a217911d","question":"Read the passage. Grade 5 foundation passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["The school choir rehearsed a song about the moon.","She showed how helmets should sit flat and snug on a rider's head.","The passage says every reader already knew about bike safety.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Strong evidence is a fact, detail, or example from the text that directly explains or proves why a specific claim or statement is true.","example":"Claim: Dogs are helpful. Evidence: Dogs are often trained to lead people who cannot see.","strategyClue":"Look at the claim and ask yourself, 'Which sentence provides the specific fact or instruction that proves this statement is true?' Ignore sentences that talk about different topics or just give general titles.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence provides specific instructions on the proper positioning of the helmet, which directly supports the idea that correct fit is necessary for safety.","incorrect":[{"choice":"The school choir rehearsed a song about the moon.","category":"irrelevant information","reason":"This sentence has nothing to do with bike safety or helmet fit. Evidence must always relate directly to the claim being made."},"",{"choice":"The passage says every reader already knew about bike safety.","category":"unsupported claim","reason":"The text does not state that readers already know about bike safety, and even if it did, that would not explain how a helmet protects a rider."},{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"A title might introduce a topic, but it is not considered evidence because it does not provide the facts or instructions needed to support the claim about helmet fit."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":141,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0142","version":3,"contentHash":"sha256:9a42f88c963e9e10ff2dd1cbdcef28c5cc44e55a3c9e562baee53a2b1afbc2ca","question":"Read the passage. Grade 5 foundation passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["The passage says every reader already knew about city buses.","A bakery sold cinnamon rolls before sunrise.","The new route stopped near the clinic, grocery store, and community center.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To support a main idea, look for specific details, examples, or facts in the text that directly relate to the topic.","example":"Main Idea: The park is fun. Evidence: There is a new playground and a large pond for fishing.","strategyClue":"Ask yourself, 'Which sentence gives me a concrete example of the bus route helping someone?' Look for words that represent places people visit daily.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence provides direct evidence because it lists specific locations that people in a community need to visit, such as a grocery store and a clinic.","incorrect":[{"choice":"The passage says every reader already knew about city buses.","category":"unsupported claim","reason":"The passage never mentions what readers knew or thought; this sentence adds information that is not in the text."},{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"This detail is not part of the passage and does not help explain how the bus routes help the community."},"",{"choice":"The title names the topic but gives no proof.","category":"meta-commentary error","reason":"This is a statement about the text structure, not evidence from the text that shows how the bus route serves the community."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":142,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0143","version":3,"contentHash":"sha256:174e0d868879f7e828c8ff4f3ff5ae81fa6cc263d6ce1fa3d1cd591de6b216dc","question":"Read the passage. Grade 5 foundation passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["The title names the topic but gives no proof.","A math poster showed different kinds of triangles.","The passage says every reader already knew about school play.","Actors practiced lines while stage crew members painted scenery and tested lights."],"correct":3,"studyAid":{"definition":"To find the strongest evidence, look for a sentence that directly connects to the specific tasks, people, or actions required by the main idea.","example":"Claim: 'The garden was well-maintained.' Evidence: 'A gardener pruned the roses while a helper cleared the weeds.'","strategyClue":"Highlight the key words in the question—in this case, 'more than acting'—then look for a sentence that lists additional jobs like building, painting, or planning.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence explicitly describes multiple distinct roles beyond acting—such as painting and lighting—which proves that putting on the play required many different skills and tasks.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"Irrelevant detail choice","reason":"Titles often introduce a topic, but they rarely provide the specific evidence or facts needed to support a claim about what the production required."},{"choice":"A math poster showed different kinds of triangles.","category":"Off-topic information","reason":"This detail describes an object that is unrelated to the process of putting on a play or the work involved in the production."},{"choice":"The passage says every reader already knew about school play.","category":"Unsupported by text","reason":"Even if this were true, it does not explain how the play was built or what tasks were needed; it only describes the audience's knowledge."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":143,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0144","version":3,"contentHash":"sha256:035897738cacf80c16a5543d462713dbdf23f35becfddeeeb1260c1298d00250","question":"Read the passage. Grade 5 foundation passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["After several weeks, the dark compost was mixed into flower beds.","A new scoreboard was installed in the gym.","The passage says every reader already knew about compost bin.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Supporting evidence is a fact or detail from the text that proves a specific idea or claim is true.","example":"Claim: Dogs are helpful. Evidence: My dog barks to alert me when someone is at the door.","strategyClue":"Look for the sentence that describes the final 'result' or 'action' taken with the materials mentioned in the main idea.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence shows the food scraps being reused to help flowers grow, which directly supports the idea that waste can become useful.","incorrect":["",{"choice":"A new scoreboard was installed in the gym.","category":"irrelevant information","reason":"This sentence describes gym equipment. It does not mention food scraps or composting, so it cannot support the idea about waste."},{"choice":"The passage says every reader already knew about compost bin.","category":"not in text","reason":"This is not a sentence from the passage, and the text never claims that readers already know about the composting process."},{"choice":"The title names the topic but gives no proof.","category":"meta-analysis error","reason":"This sentence is a comment about a title, not a piece of evidence from the text that shows how food scraps are being put to a new use."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":144,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0145","version":3,"contentHash":"sha256:6e271cc084155ae568468cc654a08179e5d5b87c95c8257e849190e1e0cf078b","question":"Read the passage. Grade 5 foundation passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["The music teacher tuned a violin before class.","They measured rainfall, wind direction, temperature, and cloud cover every day.","The passage says every reader already knew about weather station.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting evidence is information from the text that directly proves a claim or answers a specific question.","example":"Claim: 'The dog was hungry.' Evidence: 'The dog barked at his empty bowl and paced near the kitchen.'","strategyClue":"Look for the sentence in the text that lists specific actions or items that match the keywords in the question.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. This sentence explicitly lists four different types of weather data being collected, which directly proves the students were gathering multiple kinds of information.","incorrect":[{"choice":"The music teacher tuned a violin before class.","category":"irrelevant information","reason":"This statement is not related to the passage about science students or weather patterns and provides no evidence for the claim."},"",{"choice":"The passage says every reader already knew about weather station.","category":"not in text","reason":"This statement is not present in the passage and does not address the variety of scientific measurements taken by the students."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title might identify a topic, but it does not act as evidence or specific proof of the activities the students performed."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":145,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0146","version":3,"contentHash":"sha256:733b784b0a3c83a8ea2a75dc142f1db0609d13c4fe2f8aebabd37a0f46e901d5","question":"Read the passage. Grade 5 foundation passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["The passage says every reader already knew about recycling team.","The nurse checked the first-aid supplies after lunch.","By winter break, the school ordered fewer boxes of printer paper.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To find evidence that supports an idea, look for a sentence that shows a direct result or change related to that specific topic.","example":"Idea: The garden grew well. Proof: We picked five baskets of tomatoes last week.","strategyClue":"Focus on the goal of the plan mentioned in the prompt. Look for the sentence that shows a measurable outcome or a change in quantity that matches that goal.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence provides direct evidence of a change in paper usage because it measures the specific decrease in supply orders after the new bins and reminders were put into action.","incorrect":[{"choice":"The passage says every reader already knew about recycling team.","category":"not supported by text","reason":"The passage does not mention what readers already knew; it focuses on the actions taken by the recycling team."},{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence mentions a nurse and first-aid, which has no connection to the paper-saving plan described in the passage."},"",{"choice":"The title names the topic but gives no proof.","category":"misunderstanding task","reason":"This is a statement about a title rather than a sentence from the text that proves the result of the recycling plan."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":146,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0147","version":3,"contentHash":"sha256:441dd3675925dea95a1515c07a9160087752a4b286f0aa3d30e32e761aa80e0f","question":"Read the passage. Grade 5 foundation passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["The title names the topic but gives no proof.","A rainstorm delayed the baseball game.","The passage says every reader already knew about museum exhibit.","Visitors could press buttons to hear recordings of elders telling memories."],"correct":3,"studyAid":{"definition":"Supporting evidence consists of specific facts, examples, or details from a text that directly prove or explain a stated claim.","example":"Claim: The garden is colorful. Evidence: There are bright red roses, yellow sunflowers, and purple pansies blooming.","strategyClue":"Break your target claim into two parts: 'objects' and 'personal stories.' Scan the text specifically looking for one word or phrase that matches each part of that claim.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This sentence provides evidence of personal stories, while the other sentences in the passage describe physical objects like tools, photographs, and maps. Combining these two elements proves the exhibit featured both.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"The passage does not contain a title, and simply stating a topic is not the same as providing specific evidence about what is inside the exhibit."},{"choice":"A rainstorm delayed the baseball game.","category":"unrelated content","reason":"This information is not mentioned in the passage at all and has nothing to do with the museum exhibit or its contents."},{"choice":"The passage says every reader already knew about museum exhibit.","category":"factual error","reason":"The passage never mentions what the reader already knows; it only describes the items found within the museum display."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":147,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0148","version":3,"contentHash":"sha256:e8f9eaf114d0415d0433faa5cd73138178cdd0b1cf392b510a5e945be6ebbc5e","question":"Read the passage. Grade 5 foundation passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["Each time the robot missed a turn, members adjusted the code and tested again.","The principal announced picture day over the speaker.","The passage says every reader already knew about robotics club.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Supporting evidence consists of specific facts, events, or actions from a text that prove a claim or main idea is true.","example":"Claim: 'The character was scared.' Evidence: 'He hid under his blankets and trembled when he heard the thunder.'","strategyClue":"First, identify the action that represents a 'mistake' or 'problem' in the text, then look for the sentence that explains what the team did in direct response to that specific problem.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence shows that when the robot failed (the mistake), the members gathered information by observing the error and then used that knowledge to change their approach.","incorrect":["",{"choice":"The principal announced picture day over the speaker.","category":"irrelevant information","reason":"This sentence describes an event at a school, but it does not mention the robot or how the club members learned from their work."},{"choice":"The passage says every reader already knew about robotics club.","category":"unsupported claim","reason":"The passage does not state that readers already knew about the club, nor does this idea provide evidence for learning from mistakes."},{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"A title might state a topic, but it cannot act as evidence to support the idea that the team used mistakes as information."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":148,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0149","version":3,"contentHash":"sha256:583c404d81752b1bd29d702ac8fa2257fa2a1e01d9c62064066f93d0c30a1947","question":"Read the passage. Grade 5 foundation passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["The science lab received new magnifying glasses.","Students who arrived close to the bell could still choose a quick meal.","The passage says every reader already knew about school breakfast.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence in a text, identify the claim being made and look for the specific sentence that explains the 'why' or 'how' behind that claim.","example":"Claim: The cat was sleepy. Evidence: The cat curled up on the rug and took a three-hour nap.","strategyClue":"Look for keywords in the claim—in this case, 'time' and 'before class'—and scan the passage for sentences that mention time, schedules, or arrivals.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This sentence directly describes students who have 'little time' (those arriving just before the bell) and explains that the cart provides a 'quick meal' to meet their needs.","incorrect":[{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information","reason":"This sentence mentions a science lab and equipment not found in the passage; it provides no evidence regarding the breakfast cart or student schedules."},"",{"choice":"The passage says every reader already knew about school breakfast.","category":"false information","reason":"The text never mentions what the reader already knows; you must base your answer only on the details provided in the passage."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"This is a statement about the structure of the text rather than a detail from the passage that supports the claim about time constraints."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":149,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0150","version":3,"contentHash":"sha256:11893c3b8b7b26a4e5022b37a4d5fa7a09d72de3e9b2cb7393cd81c85d15ad90","question":"Read the passage. Grade 5 foundation passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["The passage says every reader already knew about nature trail.","The post office closed early on Saturday.","They added arrows, distance signs, and small plaques naming common trees.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting evidence is a piece of information from the text that directly proves a claim or idea is true.","example":"Claim: The room was messy. Supporting Evidence: Clothes were piled on the floor and books were scattered across the desk.","strategyClue":"First, identify the keywords in the claim (e.g., 'directions' and 'information'). Then, scan the passage specifically looking for sentences that describe physical objects related to those keywords.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. This sentence directly mentions 'arrows' and 'distance signs' for directions, and 'plaques naming common trees' for information, which matches the claim perfectly.","incorrect":[{"choice":"The passage says every reader already knew about nature trail.","category":"not in passage","reason":"This information is not found in the text, and it does not provide any evidence about signs or directions."},{"choice":"The post office closed early on Saturday.","category":"irrelevant information","reason":"The passage is about park rangers and a nature trail, so a sentence about a post office is unrelated and provides no proof."},"",{"choice":"The title names the topic but gives no proof.","category":"incorrect logic","reason":"This statement describes a potential title, but the prompt asks for a sentence from the passage that supports the specific claim about signs."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":150,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
  const bank = window.QUESTION_BANK = window.QUESTION_BANK || {};
  const existing = bank["reading-comprehension-text-evidence"];
  if (existing && Array.isArray(existing.questions)) {
    const seen = new Set(existing.questions.map(question => question && question.id));
    chunkSet.questions.forEach(question => {
      if (!seen.has(question && question.id)) existing.questions.push(question);
    });
  } else {
    bank["reading-comprehension-text-evidence"] = chunkSet;
  }
})();
